/** Per-locality stats, generated by `node scripts/build-data.mjs`. Small enough for any page. */
import localitiesRaw from "./generated/localities.json";

export interface Locality {
  name: string;
  city: string;
  district: string;
  coords: [number, number];
  /** Indicative asking price per sq.ft (demo). */
  psf: number;
  landPerCent: number;
  yoy: number;
  listingCount: number;
  nearby: Partial<Record<"metro" | "it_park" | "water_metro", { name: string; km: number; status?: "under_construction" } | null>>;
  schools2km: number;
}

export const localities = localitiesRaw as Locality[];
